const ip = $input.first().json.headers?.['x-forwarded-for']?.split(',')[0]?.trim() || $input.first().json.headers?.['x-real-ip'] || 'unknown';
const today = new Date().toISOString().slice(0, 10);
const key = 'rl_trend_' + ip + '_' + today;
const staticData = $getWorkflowStaticData('global');
if (!staticData.rateLimits) staticData.rateLimits = {};
const current = staticData.rateLimits[key] || 0;
if (current >= 50) {
  return [{ json: { rateLimitExceeded: true } }];
}
staticData.rateLimits[key] = current + 1;
const body = $input.first().json.body || $input.first().json;
return [{ json: { rateLimitExceeded: false, ...body } }];

const data = $input.first().json;
const apiBody = {
  model: 'MiniMax-M3',
  max_completion_tokens: 8000,
  messages: [{ role: 'user', content: data.prompt || '' }]
};
return [{ json: { ...data, apiBody } }];

const data = $input.first().json;
let text = data.choices?.[0]?.message?.content || '';
const jsonStart = text.indexOf('{');
const jsonEnd = text.lastIndexOf('}');
if (jsonStart !== -1 && jsonEnd !== -1) text = text.slice(jsonStart, jsonEnd + 1);
let result = {};
try { result = JSON.parse(text); } catch(e) { result = { videos: [], ctaText: '' }; }
const videos = result.videos || [];
const dateStr = new Date().toLocaleDateString('tr-TR', { day: 'numeric', month: 'long', year: 'numeric' });
const sectorText = (data.sector === 'ALL' || !data.sector) ? 'Tüm Sektörler' : data.sector;
const tonesText = (data.tones || []).join(' + ');
const bizText = data.biz || 'İşletmeniz';
let emailContent = `Merhaba! ${bizText} için ${dateStr} tarihli trend video fikirleri:\n\n`;
videos.forEach(v => {
  emailContent += `#${v.rank} — ${v.title}\n`;
  emailContent += `Platform: ${v.platform} | Trend: ${v.trendScore || 'N/A'}\n`;
  emailContent += `Etiketler: ${(v.tags || []).join(', ')}\n`;
  emailContent += `Neden trend: ${v.whyTrending || ''}\n`;
  emailContent += `Markanıza uyarlama: ${v.adaptation || ''}\n\n---\n\n`;
});
const htmlBody = `<!DOCTYPE html><html lang="tr"><head><meta charset="UTF-8"></head><body style="font-family:system-ui,sans-serif;background:#F7F6F2;padding:2rem"><div style="max-width:680px;margin:0 auto;background:#fff;border-radius:16px;padding:2rem;border:0.5px solid #E2E0D8"><div style="color:#1D9E75;font-size:13px;font-weight:500;letter-spacing:.04em;margin-bottom:1.5rem">KOLAY KOBI — TREND VIDEO BULTENI</div><h1 style="font-size:22px;color:#1C1B19;margin-bottom:.4rem">Gunun Trend Video Fikirleri</h1><p style="font-size:14px;color:#6B6963;margin-bottom:2rem"><strong>${bizText}</strong> — ${sectorText}<br/>Ton: ${tonesText}<br/>Tarih: ${dateStr}</p>` + videos.map(v => `<div style="border:0.5px solid #E2E0D8;border-radius:12px;padding:1rem;margin-bottom:1rem"><div style="display:flex;align-items:center;gap:10px;margin-bottom:.75rem"><div style="width:32px;height:32px;border-radius:50%;background:#1D9E75;color:#fff;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:600">${v.rank}</div><div style="font-size:15px;font-weight:500;color:#1C1B19">${v.title}</div></div><div style="font-size:12px;color:#6B6963;margin-bottom:.5rem">${v.platform} | Trend: ${v.trendScore || 'N/A'}</div><div style="background:#DCF8C6;border-radius:0 12px 12px 12px;padding:10px 12px;font-size:13px;color:#1C1B19;line-height:1.6;margin-bottom:.5rem">${v.whyTrending || ''}</div><div style="background:#F7F6F2;border-radius:8px;padding:8px 10px;font-size:12px;color:#6B6963"><strong style="color:#1D9E75">Markaniza uyarlama:</strong> ${v.adaptation || ''}</div>${(v.tags && v.tags.length) ? `<div style="margin-top:.5rem">${v.tags.map(t => `<span style="font-size:11px;padding:2px 8px;background:#F0FAF6;border:0.5px solid #9FE1CB;border-radius:6px;color:#085041;margin-right:4px">${t}</span>`).join('')}</div>` : ''}</div>`).join('') + `<div style="background:#F0FAF6;border-radius:8px;padding:1rem;margin-top:1.5rem;text-align:center"><p style="font-size:13px;color:#0F6E56;margin:0">Bu rapor Kolay KOBİ Trend Video Bulucu ile oluşturuldu.</p><a href="https://kolaykobi.com" style="display:inline-block;background:#1D9E75;color:#fff;padding:10px 24px;border-radius:8px;text-decoration:none;font-size:14px;margin-top:.75rem">Kolay KOBİ'yi Ac</a></div></div></body></html>`;
return [{ json: {
  content: [{ type: 'text', text }],
  email: data.email || '',
  biz: bizText,
  sector: data.sector || '',
  tones: data.tones || [],
  mode: data.mode || 'instant',
  hour: data.hour || '',
  days: data.days || [],
  emailContent,
  htmlBody,
  videos,
  ctaText: result.ctaText || '',
} }];

const data = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.schedules) staticData.schedules = {};
const id = 'sch_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
staticData.schedules[id] = {
  id,
  biz: data.biz || 'İşletme',
  sector: data.sector || 'ALL',
  email: data.email || '',
  tones: data.tones || [],
  audience: data.audience || '',
  note: data.note || '',
  prompt: data.prompt || '',
  hour: data.hour,
  days: data.days || [],
  createdAt: new Date().toISOString(),
  active: true,
};
return [{ json: { ...data, scheduleId: id, scheduleSaved: true } }];
